import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {

  // ==============================
  // 1) EXTRACCIÓN Y VALIDACIONES
  // ==============================
  const active_energy_consumption = Number(
    input?.tsl_wo_work_order_attribute?.active_energy_consumption ?? 0
  );

  const billingItemCode =
    input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;

  if (!billingItemCode || billingItemCode.trim() === '' || billingItemCode === 'null') {
    return {
      ...input,
      result: {
        rule_description:
          'parameter_billingItem_code for rule Consumo de energia activa not found',
        status: 'ERROR',
      },
    };
  }

  const billingItems =
    input?.tsl_wo_work_order_attribute?.billing_items?.active_energy_billing_items ?? [];

  if (!Array.isArray(billingItems) || billingItems.length === 0) {
    return {
      ...input,
      result: {
        rule_description:
          'active_energy_billing_items not found in billing_items structure',
        status: 'ERROR',
      },
    };
  }

  // Buscar el billing item por código (NO el primero)
  const targetItem = billingItems.find(
    (bi) => String(bi?.billing_item_code ?? '').trim() === String(billingItemCode).trim()
  );

  if (!targetItem) {
    return {
      ...input,
      result: {
        rule_description: `The parameter_billingItem_code '${billingItemCode}' could not be found in the billing concepts structure`,
        status: 'ERROR',
      },
    };
  }

  // ==============================
  // 2) OBTENER ESTRUCTURA DE PRECIOS
  // ==============================
  const rawPrices =
    targetItem?.prices_and_method?.price_structure?.graduated_pricing?.prices ?? [];

  if (!Array.isArray(rawPrices) || rawPrices.length === 0) {
    return {
      ...input,
      result: {
        rule_description: `Rate prices for '${billingItemCode}' not found`,
        status: 'ERROR',
      },
    };
  }

  // Normalizar y ordenar por interval_low ASC (como solicitaste)
  const precios = rawPrices
    .map((p) => ({
      low: Number(p?.interval_low ?? 0),
      high:
        Number(p?.interval_high ?? 0) === 999999999 || p?.interval_high == null
          ? 999999999
          : Number(p.interval_high),
      price: Number(p?.base_price ?? 0),
    }))
    .sort((a, b) => a.low - b.low);

    console.log('precios',precios)

  // ==============================
  // 3) CÁLCULO ACUMULATIVO POR RANGOS
  // ==============================
  let consumo_restante = active_energy_consumption;
  let costo_total = 0;

  // Para trazabilidad
  const detalle_bloques = [];

  // Llevamos un "límite previo" para evitar solapes. Arranca en 0 kWh.
  let limite_anterior = 0;

  for (const r of precios) {
    if (consumo_restante <= 0) break;

    // Asegurar consistencia si hay huecos/solapes
    const low = Math.max(r.low, limite_anterior);
    const high = r.high;

    if (high !== 999999999 && high <= low) {
      // Rango inválido o vaciado por solape: saltar
      continue;
    }

    let consumo_rango;
    if (high === 999999999) {
      // Último rango "abierto"
      consumo_rango = consumo_restante;
    } else {
      // Ancho del bloque (sin +1 para mantener compatibilidad con tu lógica previa)
      const ancho = Math.max(0, high - low);
      if (ancho === 0) continue;
      consumo_rango = Math.min(consumo_restante, ancho);
    }

    const importe_bloque = consumo_rango * r.price;
    costo_total += importe_bloque;

    detalle_bloques.push({
      rango_inferior: r.low,
      rango_superior: r.high === 999999999 ? 'Sin límite' : r.high,
      precio_unitario: r.price,
      consumo_en_rango: consumo_rango,
      importe_bloque,
    });

    consumo_restante -= consumo_rango;
    limite_anterior = high === 999999999 ? limite_anterior + consumo_rango : high;
  }

  if (consumo_restante !== 0) {
    return {
      ...input,
      result: {
        status: 'ERROR',
        status_description: 'Consumption ranges still need to be calculated',
      },
    };
  }

  // ==============================
  // 4) ACTUALIZAR EL BILLING ITEM
  // ==============================
  targetItem.billing_item_amount = costo_total;

  // ==============================
  // 5) SALIDA
  // ==============================
  return {
    tsl_wo_work_order_attribute: { ...input.tsl_wo_work_order_attribute },
    result: {
      total_amount: costo_total,
      status: 'OK',
      status_description:
        'Consumo de energia activa calculation rule completed (prices picked by billingItemCode and sorted by interval_low asc)',
    },
  };
};
